import {host,data} from '/atlas/host.js';
import {transition} from '../tools/game.js';
const $=s=>document.querySelector(s),status=$('#status');
const scenes={landing:['Crashed at the edge of the valley','Rain ticks against the wreck. Three silent buildings blink beyond the ridge. The relay tower is your only way to call for help.'],hab:['Habitat 3','A dark habitation module. A maintenance fuse sits in an open wall panel.'],greenhouse:['Glasshouse','Overgrown vines curl around a sealed sample case. The spore vial is intact.'],relay:['Relay tower','A dead transmitter waits beneath a cracked console. The access key is etched with the previous crew’s call sign.']};
let state={room:'landing',inventory:[],won:false},recordId=null,busy=false,storage=false;
function choices(){if(state.won)return [['Signal sent — you made it','',true]];const r=state.room;let a=[];if(r==='landing')a=[['Enter Habitat 3','hab'],['Explore the Glasshouse','greenhouse'],['Climb to the Relay Tower','relay']];else{a.push(['Return to the crash site','landing']);if(r==='hab'&&!state.inventory.includes('fuse'))a.push(['Take the maintenance fuse','take_fuse']);if(r==='greenhouse'&&!state.inventory.includes('spore'))a.push(['Collect the spore sample','take_spore']);if(r==='relay'&&!state.inventory.includes('key'))a.push(['Take the access key','take_key']);if(r==='relay')a.push([state.inventory.length===3?'Install parts and transmit':'Try the transmitter (needs all three items)','transmit']);}return a;}
function draw(){const [title,text]=scenes[state.room];$('#room').textContent=state.room.toUpperCase();$('#title').textContent=state.won?'TRANSMISSION RECEIVED':title;$('#story').textContent=state.won?'A reply crackles through the static: rescue is on the way. You are no longer alone.':text;$('#story').className=state.won?'win':'';const items=$('#items');items.replaceChildren();for(const x of state.inventory){const e=document.createElement('span');e.className='item';e.textContent=({fuse:'⚡ Fuse',spore:'✿ Spore sample',key:'⌑ Access key'})[x];items.append(e)}if(!state.inventory.length){const e=document.createElement('span');e.className='empty';e.textContent='Nothing yet';items.append(e)}const box=$('#choices');box.replaceChildren();for(const [label,action,disabled] of choices()){const b=document.createElement('button');b.textContent=label;b.disabled=!!disabled||busy;b.addEventListener('click',()=>act(action));box.append(b)}}
async function save(){const page=await data.query({collection:'neon_vale_save',limit:10});const existing=recordId?page.records.find(r=>r.id===recordId):page.records[0];const request_key=Date.now().toString(36)+Math.random().toString(36).slice(2);const mutation=existing?{kind:'update',collection:'neon_vale_save',record_id:existing.id,data:{state}}:{kind:'create',collection:'neon_vale_save',data:{state}};const p=await data.prepare({expected_data_version:page.data_version,request_key,mutations:[mutation]});await data.commit(p.operation_id);const after=await data.query({collection:'neon_vale_save',limit:10});if(after.records[0])recordId=after.records[0].id;}
async function act(action){if(busy)return;busy=true;draw();const before=state;state=transition({state,action});try{if(storage)await save();status.textContent=storage?'Progress saved.':'Preview mode — progress will not persist.'}catch(e){state=before;status.textContent='Save failed: '+(e.code||e.message||'try again');}finally{busy=false;draw()}}
try{const info=await host.describe();storage=!!info.storage_authorized;if(storage){const page=await data.query({collection:'neon_vale_save',limit:10});const row=page.records?.[0];if(row){recordId=row.id;state=row.data.state||state;status.textContent='Saved expedition restored.'}else status.textContent='Your expedition is ready.'}else status.textContent='Preview mode — progress will not persist.';draw();await host.ready()}catch(e){status.textContent='Startup issue: '+(e.code||e.message||'storage unavailable');draw();try{await host.ready()}catch{}}
